DROP VIEW IF EXISTS v_atlas_verse_being, v_atlas_verse_divine;
DROP TABLE IF EXISTS verse_being, verse_divine;
CREATE TABLE verse_being (verse_id varchar(16) NOT NULL REFERENCES verse, being_id varchar(64) NOT NULL REFERENCES spiritual_being,
  source varchar(20) NOT NULL, PRIMARY KEY (verse_id, being_id));
CREATE TABLE verse_divine (verse_id varchar(16) NOT NULL REFERENCES verse, divine_id varchar(64) NOT NULL REFERENCES divine,
  source varchar(20) NOT NULL, PRIMARY KEY (verse_id, divine_id));

-- 3b. verse_manifestation: verses that record a manifestation of God (Verse -records-> Manifestation)
DROP VIEW IF EXISTS v_atlas_verse_manifestation;
DROP TABLE IF EXISTS verse_manifestation;
CREATE TABLE verse_manifestation (verse_id varchar(16) NOT NULL REFERENCES verse,
  manifestation_id varchar(64) NOT NULL REFERENCES manifestation, PRIMARY KEY (verse_id, manifestation_id));

-- 1c. curated book summaries and composition dates (cur_books.py); widen the label columns first
DROP VIEW IF EXISTS v_atlas_book;
ALTER TABLE book ALTER COLUMN composition_date_label TYPE varchar(160), ALTER COLUMN dating_basis TYPE varchar(120);
CREATE VIEW v_atlas_book AS SELECT book_id, name, short_name, book_order, testament, division, genre, original_language,
  chapter_count, verse_count, author_traditional, authorship_confidence, composition_year_start, composition_year_end,
  composition_date_label, dating_basis, summary, source FROM book;
UPDATE book SET composition_year_start = -1446, composition_year_end = -1406, composition_date_label = 'c. 1446–1406 BC, written by Moses in the wilderness', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The book of beginnings: creation, the fall, the flood and the scattering at Babel, then God''s covenant with Abraham and its passing to Isaac, Jacob and Joseph. It sets out the promise of a seed of the woman who will crush the serpent, the thread of redemption the rest of scripture follows.' WHERE book_id = 'Gen';
UPDATE book SET composition_year_start = -1446, composition_year_end = -1406, composition_date_label = 'c. 1446–1406 BC, written by Moses in the wilderness', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'God redeems Israel from slavery in Egypt by the Passover lamb and the crossing of the Red Sea, gives the Law at Sinai, and comes to dwell among his people in the tabernacle. Redemption by blood and God''s presence with his people foreshadow Christ.' WHERE book_id = 'Exod';
UPDATE book SET composition_year_start = -1446, composition_year_end = -1406, composition_date_label = 'c. 1446–1406 BC, written by Moses in the wilderness', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The manual of holiness for a redeemed people: sacrifices, the priesthood, clean and unclean, the Day of Atonement and the feasts. ''Ye shall be holy: for I the LORD your God am holy.'' Its sacrifices point to the one sacrifice of Christ (Hebrews 9–10).' WHERE book_id = 'Lev';
UPDATE book SET composition_year_start = -1446, composition_year_end = -1406, composition_date_label = 'c. 1446–1406 BC, written by Moses in the wilderness', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Israel''s forty years in the wilderness: the census at Sinai, the unbelief at Kadesh that kept a generation out of Canaan, and God''s faithful provision and judgement until the new generation stands on the plains of Moab.' WHERE book_id = 'Num';
UPDATE book SET composition_year_start = -1406, composition_year_end = -1406, composition_date_label = 'c. 1406 BC, Moses’ final addresses on the plains of Moab', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Moses'' farewell sermons renewing the covenant with the generation about to enter Canaan: the Law restated, the call to love the LORD with all the heart, blessings and curses, and the promise of a prophet like Moses. It closes with Moses'' death.' WHERE book_id = 'Deut';
UPDATE book SET composition_year_start = -1400, composition_year_end = -1370, composition_date_label = 'c. 1400–1370 BC, soon after the conquest', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'God keeps his promise to the fathers by bringing Israel into Canaan under Joshua: Jericho, the conquest of the land, its division among the tribes, and the covenant renewal at Shechem: ''as for me and my house, we will serve the LORD.''' WHERE book_id = 'Josh';
UPDATE book SET composition_year_start = -1045, composition_year_end = -1000, composition_date_label = 'c. 1045–1000 BC, early in the monarchy', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The repeated cycle of sin, oppression, crying out and deliverance through judges such as Deborah, Gideon and Samson, in days when ''every man did that which was right in his own eyes''. It shows Israel''s need of a righteous king.' WHERE book_id = 'Judg';
UPDATE book SET composition_year_start = -1010, composition_year_end = -970, composition_date_label = 'c. 1010–970 BC, during or after David’s reign', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'In the dark days of the judges, Ruth the Moabitess clings to Naomi and her God and is redeemed by Boaz, her kinsman-redeemer. Their son Obed is the grandfather of David, placing a Gentile in the line of Christ.' WHERE book_id = 'Ruth';
UPDATE book SET composition_year_start = -930, composition_year_end = -900, composition_date_label = 'c. 930–900 BC, after the kingdom divided', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The move from judges to kings: Samuel''s birth and ministry, Israel''s demand for a king, Saul''s rise and rejection, and the anointing of David, the man after God''s own heart, who waits for the throne through years of persecution.' WHERE book_id = '1Sam';
UPDATE book SET composition_year_start = -930, composition_year_end = -900, composition_date_label = 'c. 930–900 BC, after the kingdom divided', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'David''s reign: Jerusalem made his capital, the ark brought up, and God''s covenant promising David an everlasting throne, fulfilled in Christ. It also records David''s sin with Bathsheba and its bitter consequences in his house.' WHERE book_id = '2Sam';
UPDATE book SET composition_year_start = -561, composition_year_end = -538, composition_date_label = 'c. 561–538 BC, during the Exile', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Solomon''s wisdom and temple, his turning to other gods, the division of the kingdom under Rehoboam and Jeroboam, and the ministry of Elijah against Baal. Every king is measured by faithfulness to the LORD and his covenant.' WHERE book_id = '1Kgs';
UPDATE book SET composition_year_start = -561, composition_year_end = -538, composition_date_label = 'c. 561–538 BC, during the Exile (it ends with Jehoiachin’s release in 561 BC)', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Elisha''s ministry, the fall of Israel to Assyria (722 BC) and of Judah to Babylon (586 BC), with brief reforms under Hezekiah and Josiah. It explains the Exile as covenant judgement, yet ends with hope for David''s line.' WHERE book_id = '2Kgs';
UPDATE book SET composition_year_start = -450, composition_year_end = -400, composition_date_label = 'c. 450–400 BC, after the return from exile', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Israel''s history retold for the returned exiles, from Adam to David, centred on David''s line and the worship of the temple, reminding a small community that God''s covenant promises still stand.' WHERE book_id = '1Chr';
UPDATE book SET composition_year_start = -450, composition_year_end = -400, composition_date_label = 'c. 450–400 BC, after the return from exile', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The history of Judah from Solomon''s temple to the Exile and Cyrus'' decree to rebuild, showing that kings who sought the LORD prospered and those who forsook him fell. It ends with the call to go up to Jerusalem.' WHERE book_id = '2Chr';
UPDATE book SET composition_year_start = -440, composition_year_end = -400, composition_date_label = 'c. 440 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The return from Babylon under Zerubbabel, the rebuilding of the temple despite opposition, and Ezra''s later return to teach the Law and call the people to repentance for their unfaithfulness.' WHERE book_id = 'Ezra';
UPDATE book SET composition_year_start = -430, composition_year_end = -400, composition_date_label = 'c. 430–400 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Nehemiah, cupbearer to Artaxerxes, rebuilds Jerusalem''s walls in fifty-two days against fierce opposition, then joins Ezra in reading the Law and renewing the covenant, and confronts the people''s renewed sins.' WHERE book_id = 'Neh';
UPDATE book SET composition_year_start = -460, composition_year_end = -350, composition_date_label = 'c. 460–350 BC, after the reign of Ahasuerus (Xerxes)', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Esther, a Jewish queen of Persia, risks her life to save her people from Haman''s plot. God is never named, yet his providence governs every turn, ''for such a time as this.'' It explains the feast of Purim.' WHERE book_id = 'Esth';
UPDATE book SET composition_year_start = -1440, composition_year_end = -950, composition_date_label = 'Date uncertain: a patriarchal setting, written somewhere between Moses and Solomon', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A righteous man loses everything and wrestles with why the innocent suffer. His friends'' counsel fails, and God answers from the whirlwind with his sovereign majesty, humbling and restoring Job. ''I know that my redeemer liveth.''' WHERE book_id = 'Job';
UPDATE book SET composition_year_start = -1440, composition_year_end = -450, composition_date_label = 'c. 1440–450 BC, from Moses (Psalm 90) through David to after the Exile', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Israel''s inspired songbook of praise, lament, confession, thanksgiving and wisdom, largely by David. Many psalms speak of the coming Messiah, his kingship, suffering and resurrection, and are applied to Christ in the New Testament.' WHERE book_id = 'Ps';
UPDATE book SET composition_year_start = -970, composition_year_end = -700, composition_date_label = 'c. 970–700 BC: Solomon, with chapters 25–29 copied by Hezekiah’s men', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Wisdom for daily life under God: ''The fear of the LORD is the beginning of knowledge.'' Short sayings on speech, work, money, family and friendship contrast the way of wisdom with the way of the fool.' WHERE book_id = 'Prov';
UPDATE book SET composition_year_start = -940, composition_year_end = -931, composition_date_label = 'c. 940–931 BC, late in Solomon’s reign', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The Preacher tests pleasure, work, wealth and wisdom and finds all ''vanity under the sun'' when lived apart from God, concluding: ''Fear God, and keep his commandments: for this is the whole duty of man.''' WHERE book_id = 'Eccl';
UPDATE book SET composition_year_start = -970, composition_year_end = -950, composition_date_label = 'c. 970–950 BC, early in Solomon’s reign', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A poem celebrating the love of bridegroom and bride, affirming the goodness of married love. The church has long also read it as a picture of the love between Christ and his church.' WHERE book_id = 'Song';
UPDATE book SET composition_year_start = -740, composition_year_end = -681, composition_date_label = 'c. 740–681 BC, by the prophet Isaiah son of Amoz', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Judgement and comfort for Judah and the nations: Isaiah''s vision of the holy God, the virgin-born Immanuel, the suffering Servant who bears our sins (chapter 53), and the new heavens and new earth. It is called the fifth gospel.' WHERE book_id = 'Isa';
UPDATE book SET composition_year_start = -627, composition_year_end = -570, composition_date_label = 'c. 627–570 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Jeremiah, the weeping prophet, warns Judah for forty years of coming judgement by Babylon, suffers rejection and imprisonment, sees Jerusalem fall, and announces the new covenant written on the heart (31:31–34).' WHERE book_id = 'Jer';
UPDATE book SET composition_year_start = -586, composition_year_end = -584, composition_date_label = 'c. 586 BC, soon after Jerusalem fell', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Five acrostic laments over the destruction of Jerusalem and the temple, confessing that the judgement was just, yet holding to hope: ''his compassions fail not. They are new every morning: great is thy faithfulness.''' WHERE book_id = 'Lam';
UPDATE book SET composition_year_start = -593, composition_year_end = -571, composition_date_label = '593–571 BC, by Ezekiel’s dated oracles', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A priest-prophet among the exiles in Babylon sees the glory of God depart the defiled temple, announces Jerusalem''s fall, and then promises a new heart, the valley of dry bones restored to life, and the glory returning to a new temple.' WHERE book_id = 'Ezek';
UPDATE book SET composition_year_start = -605, composition_year_end = -530, composition_date_label = 'c. 605–530 BC, completed c. 530 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Daniel and his friends stay faithful in Babylon (the fiery furnace, the lions'' den) while God reveals the rise and fall of empires and the everlasting kingdom given to one like the Son of man. God rules over the kingdoms of men.' WHERE book_id = 'Dan';
UPDATE book SET composition_year_start = -755, composition_year_end = -715, composition_date_label = 'c. 755–715 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Hosea''s marriage to the unfaithful Gomer pictures Israel''s spiritual adultery and God''s steadfast, redeeming love for a faithless people: ''I will heal their backsliding, I will love them freely.''' WHERE book_id = 'Hos';
UPDATE book SET composition_year_start = -835, composition_year_end = -400, composition_date_label = 'Uncertain: c. 835 BC (early view) to after the Exile; conservative scholars differ', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A locust plague calls Judah to repentance and points to the coming day of the LORD, when God will pour out his Spirit on all flesh, fulfilled at Pentecost (Acts 2).' WHERE book_id = 'Joel';
UPDATE book SET composition_year_start = -760, composition_year_end = -750, composition_date_label = 'c. 760–750 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A shepherd of Tekoa sent to prosperous northern Israel denounces injustice, empty worship and oppression of the poor: ''let judgment run down as waters.'' It closes with the promise of David''s fallen tabernacle raised up.' WHERE book_id = 'Amos';
UPDATE book SET composition_year_start = -845, composition_year_end = -553, composition_date_label = 'Uncertain: soon after Jerusalem fell in 586 BC (most), or c. 845 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The shortest Old Testament book pronounces judgement on Edom for gloating over and joining in Judah''s downfall, and promises that ''the kingdom shall be the LORD''s.''' WHERE book_id = 'Obad';
UPDATE book SET composition_year_start = -785, composition_year_end = -760, composition_date_label = 'c. 785–760 BC, in the reign of Jeroboam II', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The prophet flees God''s call to Nineveh, is swallowed by a great fish, and preaches to a city that repents, revealing God''s mercy to the nations. Jesus cites Jonah''s three days as a sign of his own resurrection.' WHERE book_id = 'Jonah';
UPDATE book SET composition_year_start = -735, composition_year_end = -700, composition_date_label = 'c. 735–700 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Judgement on Samaria and Jerusalem for injustice and idolatry, with promises of a ruler from Bethlehem whose goings forth are from everlasting, and the call ''to do justly, and to love mercy, and to walk humbly with thy God.''' WHERE book_id = 'Mic';
UPDATE book SET composition_year_start = -663, composition_year_end = -612, composition_date_label = 'Between 663 BC (fall of Thebes) and 612 BC (fall of Nineveh)', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Announces the certain fall of Nineveh, capital of cruel Assyria, as the LORD''s just vengeance, and comfort to Judah: ''The LORD is good, a strong hold in the day of trouble.''' WHERE book_id = 'Nah';
UPDATE book SET composition_year_start = -609, composition_year_end = -598, composition_date_label = 'c. 609–598 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Habakkuk questions why God allows evil and how he can use wicked Babylon to judge Judah, and learns that ''the just shall live by his faith'', the text at the heart of the Reformation. He ends rejoicing in God amid loss.' WHERE book_id = 'Hab';
UPDATE book SET composition_year_start = -640, composition_year_end = -621, composition_date_label = 'c. 640–621 BC, under Josiah', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Warns of the great day of the LORD''s wrath on Judah and the nations, and promises a purified remnant over whom God will rejoice with singing.' WHERE book_id = 'Zeph';
UPDATE book SET composition_year_start = -520, composition_year_end = -520, composition_date_label = '520 BC (oracles dated to the second year of Darius)', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Rebukes the returned exiles for building their own houses while God''s house lies in ruins, and encourages them to rebuild, promising that the latter glory of the house shall be greater than the former.' WHERE book_id = 'Hag';
UPDATE book SET composition_year_start = -520, composition_year_end = -480, composition_date_label = 'From 520 BC; chapters 9–14 perhaps c. 480 BC', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Visions encouraging the rebuilding of the temple and messianic prophecies: the king coming lowly on a donkey, the shepherd sold for thirty pieces of silver, the pierced one, and the LORD''s final reign over all the earth.' WHERE book_id = 'Zech';
UPDATE book SET composition_year_start = -433, composition_year_end = -420, composition_date_label = 'c. 433–420 BC, in Nehemiah’s time', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The last prophet before four centuries of silence confronts careless priests, broken marriages and robbed tithes, and promises the messenger who will prepare the way and the Sun of righteousness rising with healing.' WHERE book_id = 'Mal';
UPDATE book SET composition_year_start = 50, composition_year_end = 65, composition_date_label = 'c. AD 50–65, before the fall of Jerusalem', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Written for Jewish readers, Matthew presents Jesus as the promised Messiah and King, son of David and Abraham, fulfilling the prophets, teaching in five great discourses (including the Sermon on the Mount), and sending his church to make disciples of all nations.' WHERE book_id = 'Matt';
UPDATE book SET composition_year_start = 55, composition_year_end = 65, composition_date_label = 'c. AD 55–65; by tradition from Peter’s preaching', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The brisk, action-filled gospel of Jesus the Son of God and suffering Servant, who ''came not to be ministered unto, but to minister, and to give his life a ransom for many.'' Most conservative scholars take it as the first gospel written.' WHERE book_id = 'Mark';
UPDATE book SET composition_year_start = 60, composition_year_end = 62, composition_date_label = 'c. AD 60–62', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Luke''s orderly account, written for Theophilus, presents Jesus as the Saviour of all kinds of people who ''came to seek and to save that which was lost'', with the fullest account of his birth and many parables found nowhere else.' WHERE book_id = 'Luke';
UPDATE book SET composition_year_start = 85, composition_year_end = 95, composition_date_label = 'c. AD 85–95', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Written ''that ye might believe that Jesus is the Christ, the Son of God'', John presents the eternal Word made flesh through seven signs and seven ''I am'' sayings, with the fullest record of Jesus'' teaching to his disciples before the cross.' WHERE book_id = 'John';
UPDATE book SET composition_year_start = 62, composition_year_end = 62, composition_date_label = 'c. AD 62, while Paul was under house arrest in Rome', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The risen Christ continues his work by the Holy Spirit through the apostles: Pentecost, the church in Jerusalem, Stephen''s martyrdom, Saul''s conversion, the gospel to the Gentiles, and Paul''s journeys from Jerusalem to Rome.' WHERE book_id = 'Acts';
UPDATE book SET composition_year_start = 57, composition_year_end = 57, composition_date_label = 'c. AD 57, from Corinth', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul''s fullest exposition of the gospel: all have sinned, sinners are justified by faith alone through Christ''s righteousness, freed from sin''s dominion, kept by God''s sovereign election and grace, and called to living sacrifice.' WHERE book_id = 'Rom';
UPDATE book SET composition_year_start = 55, composition_year_end = 55, composition_date_label = 'c. AD 55, from Ephesus', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul corrects a divided and worldly church on factions, immorality, lawsuits, marriage, idol food, worship and spiritual gifts, sets out the excellence of love, and defends the bodily resurrection of Christ and his people.' WHERE book_id = '1Cor';
UPDATE book SET composition_year_start = 56, composition_year_end = 56, composition_date_label = 'c. AD 56, from Macedonia', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul''s most personal letter defends his apostleship against false teachers, explains a ministry of the new covenant carried in ''earthen vessels'', and urges generous giving: God''s strength is made perfect in weakness.' WHERE book_id = '2Cor';
UPDATE book SET composition_year_start = 48, composition_year_end = 55, composition_date_label = 'c. AD 48–49 before the Jerusalem council, or c. 53–55; conservative scholars differ', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul''s urgent defence of justification by faith alone against those who added circumcision and the law: ''a man is not justified by the works of the law, but by the faith of Jesus Christ.'' Christ has set us free.' WHERE book_id = 'Gal';
UPDATE book SET composition_year_start = 60, composition_year_end = 62, composition_date_label = 'c. AD 60–62, from prison in Rome', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Every spiritual blessing in Christ: chosen before the foundation of the world, saved by grace through faith, Jew and Gentile made one body. It then sets out the church''s walk, the household and the armour of God.' WHERE book_id = 'Eph';
UPDATE book SET composition_year_start = 61, composition_year_end = 62, composition_date_label = 'c. AD 61–62, from prison in Rome', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A letter of joy from prison, thanking the Philippians for their gifts and urging humility after Christ''s example, who emptied himself and was exalted: ''For to me to live is Christ, and to die is gain.''' WHERE book_id = 'Phil';
UPDATE book SET composition_year_start = 60, composition_year_end = 62, composition_date_label = 'c. AD 60–62, from prison in Rome', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul answers a false philosophy at Colossae by proclaiming the supremacy and sufficiency of Christ, the image of the invisible God in whom all the fullness of the Godhead dwells bodily.' WHERE book_id = 'Col';
UPDATE book SET composition_year_start = 50, composition_year_end = 51, composition_date_label = 'c. AD 50–51, from Corinth', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul commends a young church for its faith under persecution, defends his conduct, urges holy living, and comforts them about believers who have died, who will rise at Christ''s return.' WHERE book_id = '1Thess';
UPDATE book SET composition_year_start = 51, composition_year_end = 52, composition_date_label = 'c. AD 51–52, from Corinth', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Corrects the belief that the day of the Lord had already come, describing the man of sin who must first be revealed, and rebukes those who had stopped working.' WHERE book_id = '2Thess';
UPDATE book SET composition_year_start = 62, composition_year_end = 64, composition_date_label = 'c. AD 62–64', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Instructions to Timothy at Ephesus on guarding sound doctrine against false teachers, ordering public worship, and the qualifications of elders and deacons, for the church is ''the pillar and ground of the truth.''' WHERE book_id = '1Tim';
UPDATE book SET composition_year_start = 64, composition_year_end = 67, composition_date_label = 'c. AD 64–67, Paul’s last letter, shortly before his martyrdom', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Paul''s final charge from a Roman prison: guard the gospel, endure hardship, and preach the word, because ''all scripture is given by inspiration of God.'' ''I have fought a good fight... I have kept the faith.''' WHERE book_id = '2Tim';
UPDATE book SET composition_year_start = 62, composition_year_end = 64, composition_date_label = 'c. AD 62–64', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Directions to Titus in Crete on appointing elders and teaching sound doctrine, grounding godly living in the grace of God that has appeared, bringing salvation.' WHERE book_id = 'Titus';
UPDATE book SET composition_year_start = 60, composition_year_end = 62, composition_date_label = 'c. AD 60–62, from prison in Rome', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A personal appeal to Philemon to receive back his runaway slave Onesimus, now a believer, ''not now as a servant, but... a brother beloved'', a living picture of reconciliation in Christ.' WHERE book_id = 'Phlm';
UPDATE book SET composition_year_start = 64, composition_year_end = 69, composition_date_label = 'Before AD 70: the temple sacrifices are spoken of as still going on', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A word of exhortation to Hebrew Christians tempted to turn back: Christ is better than the angels, Moses and the Levitical priesthood, the great high priest of a better covenant whose one sacrifice is final. The author is unknown.' WHERE book_id = 'Heb';
UPDATE book SET composition_year_start = 45, composition_year_end = 49, composition_date_label = 'c. AD 45–49, perhaps the earliest New Testament book', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Practical wisdom for scattered Jewish believers: endure trials, be doers of the word, show no partiality, tame the tongue. Faith without works is dead: true faith shows itself in obedience.' WHERE book_id = 'Jas';
UPDATE book SET composition_year_start = 62, composition_year_end = 64, composition_date_label = 'c. AD 62–64, from Rome', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Peter encourages Christians suffering for their faith as elect exiles, born again to a living hope, to follow the example of Christ who suffered for them, and to live holy lives among unbelievers.' WHERE book_id = '1Pet';
UPDATE book SET composition_year_start = 64, composition_year_end = 68, composition_date_label = 'c. AD 64–68, shortly before Peter’s death', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Peter''s farewell urges growth in grace, warns against false teachers who deny Christ''s return, affirms the inspiration of scripture, and promises the day of the Lord and new heavens and a new earth.' WHERE book_id = '2Pet';
UPDATE book SET composition_year_start = 85, composition_year_end = 95, composition_date_label = 'c. AD 85–95', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'Written ''that ye may know that ye have eternal life'': tests of true faith (believing that Jesus Christ has come in the flesh, obeying his commands, and loving the brethren) against false teachers. ''God is love.''' WHERE book_id = '1John';
UPDATE book SET composition_year_start = 85, composition_year_end = 95, composition_date_label = 'c. AD 85–95', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A short letter to ''the elect lady and her children'' urging them to walk in truth and love and not to receive teachers who deny that Jesus Christ has come in the flesh.' WHERE book_id = '2John';
UPDATE book SET composition_year_start = 85, composition_year_end = 95, composition_date_label = 'c. AD 85–95', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'A personal letter commending Gaius for his hospitality to travelling missionaries, rebuking the domineering Diotrephes, and commending Demetrius.' WHERE book_id = '3John';
UPDATE book SET composition_year_start = 65, composition_year_end = 80, composition_date_label = 'c. AD 65–80', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'An urgent call to ''contend for the faith which was once delivered unto the saints'' against ungodly men who turn grace into licence, closing with a great doxology to him who is able to keep you from falling.' WHERE book_id = 'Jude';
UPDATE book SET composition_year_start = 64, composition_year_end = 96, composition_date_label = 'c. AD 95 (traditional), or before AD 70 (a view R.C. Sproul took seriously); conservative scholars differ', dating_basis = 'Conservative Reformed evangelical (Ligonier; Reformation Study Bible)', summary = 'The revelation of Jesus Christ given to John on Patmos: letters to seven churches, visions of the throne of God and the Lamb who was slain, the judgements of God, the defeat of Satan, and the new heaven and new earth where God dwells with his people.' WHERE book_id = 'Rev';
UPDATE book SET author_traditional = 'John Mark' WHERE book_id = 'Mark';
UPDATE book SET author_traditional = 'Peter' WHERE book_id = '1Pet';
UPDATE book SET author_traditional = 'Peter' WHERE book_id = '2Pet';
UPDATE book SET author_traditional = 'Unknown' WHERE book_id = 'Heb';

